final pThemeService = Provider<ThemeService>((ref) {
  return ThemeService.instance;
});

class ThemeService {
  // Bump this WHENEVER a bundled theme.json changes, and bump the matching
  // "version" inside dark.zip / light.zip to the same number. The update path
  // is gated on `installed.version < _currentDefaultThemeVersion`, so a theme
  // edit that does not move both numbers ships inside the APK and is then
  // ignored: the copy already in the database wins, and the change looks like
  // it silently did nothing.
  // 27: coin.bitfinite #2F6BFF -> Brandkit blue-600 #0644F1
  // 28: accent_color_blue #2F6BFF -> #0644F1 (one brand blue across fills and
  //     accents; as text on white this also goes 4.50:1 -> 6.76:1)
  // 29: light text_field_default_bg -> #FFFFFF per the redesign (inputs are
  //     white surfaces on the tinted page). active_bg keeps the old grey so
  //     focus is still a visible change now that resting state is white.
  // 30: the last 11 (light) / 12 (dark) tokens still holding the legacy
  //     #2F6BFF — primary buttons, switches, checkboxes, radios, the
  //     highlighted nav icon. White on #2F6BFF measures 4.4956:1, just under
  //     the 4.5 AA floor, so every primary button was marginally failing.
  //     Light takes blue-600 #0644F1 (6.25:1 vs page, 6.76:1 under white).
  //     Dark CANNOT take blue-600 — on the #12151C ground it drops to 2.70:1,
  //     under the 3:1 UI-component floor. It takes blue-700 #2258E6, the only
  //     step passing both sides (3.14:1 vs page, 5.82:1 under white).
  // 31: new text_field_default_border token (#E4E4E7 light / #2A3447 dark).
  //     A white field on the tinted page is 1.08:1 — the control had no
  //     visible edge. Note the spec's border is 1.27:1 against the field, so
  //     it is an affordance, not a WCAG 1.4.11 boundary; darkening it to
  //     >=3:1 is a deliberate open decision, not an oversight.
  // 32: coins.icons gains a "pepecoin" entry and the icon file behind it.
  //     Without it Pepecoin fell through to the bitcoincash placeholder — the
  //     same fallback BitFinite uses — so the two coins were indistinguishable
  //     in the wallet list.
  // 33: the same for coins.images and coins.secondaries. Only the small icon
  //     was registered in 32, so anywhere the big art is used — the "Add
  //     Pepecoin wallet" screen most visibly — fell through to
  //     coin_placeholder, which is BitFinite's own blue logo. Adding a coin
  //     needs all three slots, not just the one you happened to look at.
  // 34: Bellscoin lands with all three coins.* slots at once (icons, images,
  //     secondaries — the version-32/33 lesson applied up front) plus the
  //     Bellscoin.svg/bellscoin.svg files behind them. White bell on the
  //     #FFBC42 brand yellow, drawn in the same flat circle style as the
  //     other small icons.
  // 35: that hand-drawn bell replaced with the OFFICIAL Bells mark — the
  //     bell-bag-with-star vector from Nintondo's own website repo
  //     (Nintondo/website src/assets/bells.svg, 1024x1024, plain paths).
  //     Nothing else in the coin's chain of custody ships vector art: the
  //     node's qt res/src still carries stock Bitcoin Core's logo and
  //     bellscoin.com's sprite holds only social icons.
  // 36: colors.coin gains "bellscoin" — dark amber (#845400 light / #8A5804
  //     dark), replacing the brand gold #FFBC42 the hero wore at launch.
  //     heroInk is white in every theme and white on the gold measured
  //     1.68:1; the ambers measure 6.46/6.04 under white with the dark
  //     theme's hero at 3.03:1 against the page. The bell-bag icon keeps
  //     the gold; only surfaces carrying white ink darken. The same BFX
  //     blue-600 lesson, applied to the second coin that needed it.
  // 37: bellscoin coin colour moves onto the official Bells palette —
  //     Leather Brown, contrast-tuned (#7E5832 light / #855D35 dark; the
  //     published #8C6239 puts 0.8-opacity labels at 4.10:1). Bell Bag Gold
  //     #F3C532 measures 1.64:1 under white ink and stays in the icon only.
  // 38: bellscoin returns to Bell Bag Gold #F3C532 — the palette's lead
  //     colour — because heroInk() is now adaptive (white or near-black by
  //     contrast), so a light fill no longer forces a darkened surface.
  //     White on the gold is 1.64:1; the dark ink it now takes is 11.08:1.
  // 39: BitFinite finally gets its own coins.* art — the Brandkit circle
  //     mark (proper blue-600) at 512px, PNG-in-SVG like the placeholder it
  //     replaces. Registered in all three slots at once, and the bundled-
  //     theme fallback then serves it under external themes too, ending the
  //     teal-placeholder ₿ the externals painted BFX with.
  static const _currentDefaultThemeVersion = 39;
  ThemeService._();
  static ThemeService? _instance;
  static ThemeService get instance => _instance ??= ThemeService._();

  static const String baseServerUrl = "https://themes.bitfinitechain.org";

  MainDB? _db;
  MainDB get db => _db!;

  void init(MainDB db) => _db ??= db;

  HTTP client = HTTP();

  Future<void> install({required Uint8List themeArchiveData}) async {
    final themesDir = StackFileSystem.themesDir!;

    final archive = ZipDecoder().decodeBytes(themeArchiveData);

    final themeJsonFiles = archive.files.where((e) => e.name == "theme.json");

    if (themeJsonFiles.length != 1) {
      throw Exception("Invalid theme archive: Missing theme.json");
    }

    final jsonString = utf8.decode(themeJsonFiles.first.content as List<int>);
    final json = jsonDecode(jsonString) as Map;

    final theme = StackTheme.fromJson(json: Map<String, dynamic>.from(json));

    try {
      theme.assets;
    } catch (_) {
      throw Exception("Invalid theme: Failed to create assets object");
    }

    final String assetsPath = "${themesDir.path}/${theme.themeId}";

    for (final file in archive.files) {
      if (file.isFile) {
        // TODO more sanitation?
        if (file.name.contains("..")) {
          Logging.instance.e(
            "Bad theme asset file path: ${file.name}",
            stackTrace: StackTrace.current,
          );
        } else {
          final os = OutputFileStream("$assetsPath/${file.name}");
          file.writeContent(os);
          await os.close();
        }
      }
    }

    await db.isar.writeTxn(() async {
      await db.isar.stackThemes.put(theme);
    });
  }

  Future<void> remove({required String themeId}) async {
    final themesDir = StackFileSystem.themesDir!;
    final isarId = await db.isar.stackThemes
        .where()
        .themeIdEqualTo(themeId)
        .idProperty()
        .findFirst();
    if (isarId != null) {
      await db.isar.writeTxn(() async {
        await db.isar.stackThemes.delete(isarId);
      });
      final dir = Directory("${themesDir.path}/$themeId");
      if (dir.existsSync()) {
        await dir.delete(recursive: true);
      }
    } else {
      Logging.instance.w(
        "Failed to delete theme $themeId",
        stackTrace: StackTrace.current,
      );
    }
  }

  Future<void> checkDefaultThemesOnStartup() async {
    // install default themes
    if (!(await ThemeService.instance.verifyInstalled(themeId: "light"))) {
      await _updateDefaultTheme("light");
    } else {
      // check installed version
      final theme = ThemeService.instance.getTheme(themeId: "light");
      if ((theme?.version ?? 1) < _currentDefaultThemeVersion) {
        await _updateDefaultTheme("light");
      }
    }
    if (AppConfig.hasFeature(AppFeature.themeSelection)) {
      if (!(await ThemeService.instance.verifyInstalled(themeId: "dark"))) {
        await _updateDefaultTheme("dark");
      } else {
        // check installed version
        final theme = ThemeService.instance.getTheme(themeId: "dark");
        if ((theme?.version ?? 1) < _currentDefaultThemeVersion) {
          await _updateDefaultTheme("dark");
        }
      }
    }
  }

  Future<void> _updateDefaultTheme(String name) async {
    Logging.instance.w("Updating default $name theme...");
    final zip = await rootBundle.load("assets/default_themes/$name.zip");
    await ThemeService.instance.install(
      themeArchiveData: zip.buffer.asUint8List(),
    );
    Logging.instance.w("Updating default $name theme... finished");
  }

  // TODO more thorough check/verification of theme
  Future<bool> verifyInstalled({required String themeId}) async {
    final theme = await db.isar.stackThemes
        .where()
        .themeIdEqualTo(themeId)
        .findFirst();
    if (theme != null) {
      try {
        theme.assets;
      } catch (_) {
        return false;
      }

      final themesDir = StackFileSystem.themesDir!;
      final jsonFileExists = await File(
        "${themesDir.path}/$themeId/theme.json",
      ).exists();
      final assetsDirExists = await Directory(
        "${themesDir.path}/$themeId/assets",
      ).exists();

      if (!jsonFileExists || !assetsDirExists) {
        Logging.instance.w(
          "Theme $themeId found in DB but is missing files",
          stackTrace: StackTrace.current,
        );
      }

      return jsonFileExists && assetsDirExists;
    } else {
      return false;
    }
  }

  Future<List<StackThemeMetaData>> fetchThemes() async {
    try {
      final response = await client.get(
        url: Uri.parse("$baseServerUrl/themes"),
        proxyInfo: !AppConfig.hasFeature(AppFeature.tor)
            ? null
            : Prefs.instance.useTor
            ? TorService.sharedInstance.getProxyInfo()
            : null,
      );

      final jsonList = jsonDecode(response.body) as List;

      final result = List<Map<String, dynamic>>.from(jsonList)
          .map((e) => StackThemeMetaData.fromMap(e))
          .where((e) => e.id != "light" && e.id != "dark")
          .toList();

      return result;
    } catch (e, s) {
      Logging.instance.w(
        "Failed to fetch themes list: ",
        error: e,
        stackTrace: s,
      );
      rethrow;
    }
  }

  Future<Uint8List> fetchTheme({
    required StackThemeMetaData themeMetaData,
  }) async {
    try {
      final response = await client.get(
        url: Uri.parse("$baseServerUrl/theme/${themeMetaData.id}"),
        proxyInfo: !AppConfig.hasFeature(AppFeature.tor)
            ? null
            : Prefs.instance.useTor
            ? TorService.sharedInstance.getProxyInfo()
            : null,
      );

      final bytes = Uint8List.fromList(response.bodyBytes);

      // verify hash
      final digest = sha256.convert(bytes);
      if (digest.toString() == themeMetaData.sha256) {
        return bytes;
      } else {
        throw Exception(
          "Fetched theme archive sha256 hash ($digest) does not"
          " match requested $themeMetaData",
        );
      }
    } catch (e, s) {
      Logging.instance.w(
        "Failed to fetch themes list: ",
        error: e,
        stackTrace: s,
      );
      rethrow;
    }
  }

  StackTheme? getTheme({required String themeId}) =>
      db.isar.stackThemes.where().themeIdEqualTo(themeId).findFirstSync();

  List<StackTheme> get installedThemes =>
      db.isar.stackThemes.where().findAllSync();
}

class StackThemeMetaData {
  final String name;
  final String id;
  final int version;
  final String sha256;
  final String size;
  final String previewImageUrl;

  StackThemeMetaData({
    required this.name,
    required this.id,
    required this.version,
    required this.sha256,
    required this.size,
    required this.previewImageUrl,
  });

  static StackThemeMetaData fromMap(Map<String, dynamic> map) {
    try {
      return StackThemeMetaData(
        name: map["name"] as String,
        id: map["id"] as String,
        version: map["version"] as int? ?? 1,
        sha256: map["sha256"] as String,
        size: map["size"] as String,
        previewImageUrl: map["previewImageUrl"] as String,
      );
    } catch (e, s) {
      Logging.instance.f(
        "Failed to create instance of StackThemeMetaData using $map",
        error: e,
        stackTrace: s,
      );
      rethrow;
    }
  }

  @override
  String toString() {
    return "$runtimeType("
        "name: $name, "
        "id: $id, "
        "version: $version, "
        "sha256: $sha256, "
        "size: $size, "
        "previewImageUrl: $previewImageUrl"
        ")";
  }
}
